head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setFocusedMultiCell(1, 1);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setFocusedMultiCell(0, 1, totalRow - 1, 1);
};
scwin.trigger3_onclick = function(e) {
    gridView1.setFocusedMultiCell(0, 0, totalRow - 1, totalCol - 1);
};
scwin.trigger4_onclick = function(e) {
    gridView1.removeFocusedMultiCell(0, 0, totalRow - 1, totalCol - 1);
};
scwin.isCheckValid = function(x1, x2, y1, y2) {
    var focusedCellInfos = gridView1.focusedCell;
    var focusedCellMin = [focusedCellInfos[0].focusedRowIndex, focusedCellInfos[0].focusedColIndex];
    var focusedCellMax = [focusedCellInfos[focusedCellInfos.length - 1].focusedRowIndex, focusedCellInfos[focusedCellInfos.length - 1].focusedColIndex];
    return (focusedCellMin[0] <= x1 && focusedCellMin[1] <= x2) && (y1 <= focusedCellMax[0] && y2 <= focusedCellMax[1]);
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    //cell단위포커스
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.isCheckValid(1, 1, 1, 1)", "true");
    //column단위포커스
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.isCheckValid(0, 1, 9, 1)", "true");
    //전체포커스
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.isCheckValid(0, 0, 9, 2)", "true");
    //전체포커스 아웃
    //WebSquare.wUnit.addCommand("set","WebSquare.wUnit.getDomById('trigger4').click()");
    //WebSquare.wUnit.addCommand("assert", "scwin.isCheckValid(0, 0, 9, 2)", "true");	
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.arr = [];
    for (var i = 0; i < 30; i++) {
        arr[i] = i;
    }
    dataList1.setData(arr);
    window.totalRow = dataList1.getTotalRow();
    window.totalCol = dataList1.getTotalCol();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
